-- GenDB engine variant Q14-commuted_comparisons: template q14.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  100.00 * SUM(
    CASE
      WHEN p_type LIKE 'PROMO%'
      THEN l_extendedprice * (
        1 - l_discount
      )
      ELSE 0
    END
  ) / SUM(l_extendedprice * (
    1 - l_discount
  )) AS promo_revenue
FROM lineitem, part
WHERE
  p_partkey = l_partkey
  AND $1 <= l_shipdate
  AND $1 + INTERVAL '1 MONTH' > l_shipdate
